1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	/** Levied on every quote, not only the customer's first — see the policy-wide modifier rules. */
43	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
44	
45	/** The MHPCO price list; only the types pinned down by tests so far. */
46	const BASE_PREMIUMS: Record<string, number> = {
47	  sword: 100,
48	  amulet: 60,
49	  staff: 80,
50	  potion: 40,
51	};
52	
53	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
54	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
55	
56	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
57	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
58	
59	const basePremiumFor = (item: Item): number => BASE_PREMIUMS[item.type];
60	
61	const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);
62	
63	const quote = (step: QuoteStep): StepResult => {
64	  const basePremium = sum(step.items.map(basePremiumFor));
65	  return {
66	    premium: roundUpToWholeG(basePremium * (1 + INITIAL_ASSESSMENT_SURCHARGE) + PROCESSING_FEE),
67	  };
68	};
69	
70	const runStep = (step: Step): StepResult => {
71	  if (step.op === "quote") return quote(step);
72	  throw new Error(`Unsupported step: ${step.op}`);
73	};
74	
75	export const runScenario = (scenario: Scenario): ScenarioResult => ({
76	  results: scenario.steps.map(runStep),
77	});
